"""kdb emit: write a standalone script for an engine with the parameters baked in."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Dict

from ..data import repo_root

PY_TEMPLATE = '''#!/usr/bin/env python3
"""Standalone kdb run (python engine), generated by `kdb emit`.  Requires the kdb package (pip install -e .).

recipe: {recipe}
params: {params}
"""
import json
from kdb.recipes import run_{recipe}

PARAMS = {params_py}

if __name__ == "__main__":
    print(json.dumps(run_{recipe}(PARAMS), indent=1))
'''


def _wl_value(v):
    if isinstance(v, bool):
        return "True" if v else "False"
    if isinstance(v, (int, float)):
        return repr(v)
    return '"' + str(v).replace('"', '\\"') + '"'


def emit(recipe: str, engine: str, params: Dict, output: str) -> Path:
    out = Path(output)
    if engine == "python":
        text = PY_TEMPLATE.format(recipe=recipe, params=json.dumps(params), params_py=repr(params))
    elif engine == "sage":
        body = (repo_root() / "recipes" / recipe / "run.sage").read_text()
        text = f"# generated by kdb emit; parameters baked in\nPARAMS = {params!r}\n" + body
    elif engine == "wolfram":
        body = (repo_root() / "recipes" / recipe / "run.wl").read_text()
        assoc = "<|" + ", ".join(f'"{k}" -> {_wl_value(v)}' for k, v in params.items()) + "|>"
        text = f"(* generated by kdb emit; parameters baked in *)\nPARAMS = {assoc};\n" + body
    else:
        raise ValueError(engine)
    out.write_text(text)
    return out
